    {
        [ColumnName("PredictedLabel")]
        public bool Prediction { get; set; }
        [ColumnName("Score")]
        public float Probability { get; set; }
        [ColumnName("Features")]
        public float[] Features { get; set; }
        [ColumnName("Label")]
        public string Sentiment { get; set; }
        [ColumnName("Sentence")]
        public string Sentence { get; set; }
    }
    public class Sentiment
    {
        public string Sentence { get; set; }
        public string Sentiment { get; set; }
    }
}
```
