```matlab
% Load the necessary libraries
addpath('face_detection');
addpath('emotion_detection');
% Initialize the emotion detection model
model = load('emotion_detection_model.mat');
% Initialize the face detection model
faceDetector = vision.CascadeObjectDetector();
% Create a video input object
video = videoinput('winvideo', 1, 'MJPG_640x480');
% Set the video input object properties
set(video, 'FramesPerTrigger', Inf);
set(video, 'ReturnedColorspace', 'rgb');
% Start the video capture
start(video);
% Initialize the figure
figure;
% Loop through the video frames
while true
    % Capture the current frame
    frame = getdata(video, 1);

    % Detect faces in the current frame
    bbox = step(faceDetector, frame);

    % Loop through the detected faces
    for i = 1:size(bbox, 1)
        % Extract the current face
        face = imcrop(frame, bbox(i, :));

        % Resize the face to the required size for the emotion detection model
        face = imresize(face, [48 48]);

        % Convert the face to grayscale
        face = rgb2gray(face);

        % Perform emotion detection on the current face
        emotion = predict(model.net, face);

        % Draw a rectangle around the current face
        rectangle('Position', bbox(i, :), 'LineWidth', 2, 'EdgeColor', 'r');

        % Display the current emotion label above the current face
        text(bbox(i, 1), bbox(i, 2) - 20, char(emotion), 'Color', 'r', 'FontSize', 14, 'FontWeight', 'bold');
    end

    % Display the current frame
    imshow(frame);

    % Pause for a short time to allow the figure to update
    pause(0.01);
end
% Stop the video capture
stop(video);
% Clean up the video input object
