```scala
import java.sql.DriverManager
import scala.collection.mutable.ListBuffer
object EmployeeHierarchy {
  def main(args: Array[String]): Unit = {
    val url = "jdbc:mysql://localhost:3306/employee_db"
    val driver = "com.mysql.jdbc.Driver"
    val username = "root"
    val password = "password"
    var connection: java.sql.Connection = null
    var resultSet: java.sql.ResultSet = null
    try {
      Class.forName(driver)
      connection = DriverManager.getConnection(url, username, password)
      val statement = connection.createStatement()
      val query = "SELECT employee_id, employee_name, department, job_title, manager_id FROM Employee"
      resultSet = statement.executeQuery(query)
      val employees = new ListBuffer[(String, String, String, String, Int, Int)]()
      while (resultSet.next()) {
        employees += ((resultSet.getString("employee_name"),
          resultSet.getString("department"),
          resultSet.getString("job_title"),
          "level_" + getLevel(resultSet.getInt("employee_id"), resultSet.getInt("manager_id"), employees),
          resultSet.getInt("employee_id"),
          resultSet.getInt("manager_id")
        ))
      }
      val sortedEmployees = employees.sortBy(_._4)
      println("Employee Name\tDepartment\tJob Title\tHierarchy Level")
      for (employee <- sortedEmployees) {
        println(employee._1 + "\t" + employee._2 + "\t" + employee._3 + "\t" + employee._4)
      }
    } catch {
      case e: Exception => e.printStackTrace()
    }
    connection.close()
  }
  def getLevel(employeeId: Int, managerId: Int, employees: ListBuffer[(String, String, String, String, Int, Int)]): Int = {
    if (managerId == 0) {
      return 0
    }
    for (employee <- employees) {
      if (employee._5 == managerId) {
        return 1 + getLevel(managerId, employee._6, employees)
      }
    }
    return 0
  }
}
```
This code assumes that you have a MySQL database named "employee_db" and a table named "Employee" with the columns "employee_id", "employee_name", "department", "job_title", and "manager_id". You will need to replace the database URL, username, and password with your own.
The code uses a ListBuffer to store the employees and their hierarchy levels. It first retrieves all the employees from the database and for each employee, it calculates their hierarchy level using the getLevel function. The getLevel function recursively traverses the employee hierarchy until it reaches the top-level manager (whose manager_id is 0). The code then sorts the employees by their hierarchy level and prints out the employee name, department, job title, and hierarchy level for each employee.
