Sure, here is a sample code for binary search algorithm in C++:
```
#include <iostream>
using namespace std;
int binarySearch(int arr[], int left, int right, int x) {
   if (right >= left) {
      int mid = left + (right - left) / 2;
      if (arr[mid] == x) {
         return mid;
      }
      if (arr[mid] > x) {
         return binarySearch(arr, left, mid - 1, x);
      }
      return binarySearch(arr, mid + 1, right, x);
   }
   return -1;
}
int main() {
   int arr[] = { 2, 4, 6, 8, 10 };
   int n = sizeof(arr) / sizeof(arr[0]);
   int x = 8;
   int result = binarySearch(arr, 0, n - 1, x);
   if (result == -1) {
      cout << "Element is not present in array";
   }
   else {
      cout << "Element is present at index " << result;
   }
   return 0;
}
```
The time complexity of binary search is O(log n), whereas the time complexity of linear search is O(n). This means that binary search is much faster than linear search for large arrays, but it requires the array to be sorted.

