Yes, I can help you create a function in Swift that can accurately determine if a sentence is declarative or interrogative. Here's a possible solution:
```
func classifySentence(_ sentence: String) -> String {
    let words = sentence.components(separatedBy: " ")
    let lastWord = words.last?.lowercased() ?? ""
    let punctuation = sentence.last ?? "."
    if lastWord == "?" {
        return "interrogative"
    } else if punctuation == "." {
        return "declarative"
    } else {
        let verbTags = ["VB", "VBD", "VBG", "VBN", "VBP", "VBZ"]
        let tagger = NSLinguisticTagger(tagSchemes: [.lexicalClass], options: 0)
        tagger.string = sentence

        var verbCount = 0
        var subjectCount = 0

        tagger.enumerateTags(in: NSRange(location: 0, length: sentence.utf16.count), unit: .word, scheme: .lexicalClass) { tag, _, _, _ in
            guard let tag = tag else { return }
            let tagValue = tag.rawValue

            if verbTags.contains(tagValue) {
                verbCount += 1
            } else if tagValue == "NN" || tagValue == "NNS" || tagValue == "NNP" || tagValue == "NNPS" {
                subjectCount += 1
            }
        }

        if verbCount == 1 && subjectCount == 1 {
            return "declarative"
        } else {
            return "interrogative"
        }
    }
}
```
This function uses a combination of logical and linguistic reasoning to classify a sentence as declarative or interrogative. 
First, it checks if the last word of the sentence is a question mark. If so, the sentence is classified as interrogative.
If the sentence doesn't end with a question mark, it checks if it ends with a period. If so, the sentence is classified as declarative.
If the sentence doesn't end with a question mark or a period, it uses linguistic analysis to determine the sentence type. Specifically, it counts the number of verbs and subjects in the sentence. If there is only one verb and one subject, the sentence is classified as declarative. Otherwise, it is classified as interrogative.
Note that this solution is not perfect and may not work for all variations of sentences. However, it should work for many common cases.

