// Define the probability of a note being a rest
const double rest_probability = 0.1;
// Define the probability of a note being a chord tone
const double chord_probability = 0.8;
// Define the probability of a note being a passing tone
const double passing_probability = 0.1;
// Define the probability of a note being a neighbor tone
const double neighbor_probability = 0.1;
// Define a function to generate a random note from the chromatic scale
std::string random_note() {
    static std::random_device rd;
    static std::mt19937 gen(rd());
    static std::uniform_int_distribution<> dis(0, chromatic_scale.size() - 1);
    return chromatic_scale[dis(gen)];
}
// Define a function to generate a melody
std::vector<std::string> generate_melody(std::string key) {
    std::vector<std::string> melody;
    for (int i = 0; i < num_measures * notes_per_measure; i++) {
        if (i % notes_per_measure == 0) {
            // Add a chord tone on the first beat of each measure
            melody.push_back(key);
        } else {
