            double r = static_cast<double>(rand()) / RAND_MAX;
            if (r < rest_probability) {
                melody.push_back("R");
            } else if (r < rest_probability + chord_probability) {
                melody.push_back(key);
            } else if (r < rest_probability + chord_probability + passing_probability) {
                int direction = rand() % 2 == 0 ? -1 : 1;
                int interval = rand() % 2 + 1;
                int index = chromatic_scale.find(key);
                index = (index + direction * interval) % chromatic_scale.size();
                melody.push_back(chromatic_scale[index]);
            } else {
                int direction = rand() % 2 == 0 ? -1 : 1;
                int index = chromatic_scale.find(key);
                index = (index + direction) % chromatic_scale.size();
                melody.push_back(chromatic_scale[index]);
            }
        }
    }
    return melody;
}
int main() {
